function playPhoneme5(i){const item=PHONEME_AUDIO5[i];if(!item)return;stopMedia();phonemePlayer5=new Audio('https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(item[1]));phonemePlayer5.play().catch(()=>showModal('<h2>تعذّر تحميل التسجيل</h2><p>هذا التسجيل يحتاج الإنترنت. افتح رابط المصدر بجوار الصوت للاستماع مباشرة.</p>'));}
