EXTRA_VIEWS.phonetics=function(){$('#app').innerHTML=`<div class="view-head"><h1>مختبر النطق</h1><p>الصوت، ثم الكلمة، ثم الجملة. اسمع وكرر قبل الاعتماد على التهجئة المساعدة.</p></div><button class="primary" onclick="audioSettings4()">اختيار الصوت والسرعة</button><h2>تسجيلات للأصوات</h2><p>تسجيلات بشرية تحتاج الإنترنت. لا نستخدم قارئ النصوص لنطق رمز IPA.</p><div class="phoneme-grid5">${PHONEME_AUDIO5.map(([symbol,file,author,note],i)=>`<article class="panel"><h3 dir="ltr">[${symbol}]</h3><p>${note}</p><button class="secondary" data-phoneme5="${i}">اسمع نموذج الصوت</button><p class="source-evidence"><a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file)}" target="_blank" rel="noopener noreferrer">المصدر: ${author}</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a> · بلا تعديل</p></article>`).join('')}</div><h2>تدريب الكلمات والجمل</h2><div class="lesson-grid">${PHONETICS.map(([title,_,note,sentence],i)=>`<article class="panel"><span class="badge">تدريب ${i+1}</span><h3 dir="auto">${esc(title)}</h3><p>${esc(note)}</p>${PHONETIC_WORDS5[i].map(w=>`<div class="sound-word5"><strong class="de" lang="de">${esc(w)}</strong>${audioButton4(w,'اسمع الكلمة')}${hintsHTML5(w)}</div>`).join('')}<p class="de" lang="de">${esc(sentence)}</p>${sentenceTools5(sentence)}</article>`).join('')}</div>`;document.querySelectorAll('[data-phoneme5]').forEach(b=>b.onclick=()=>playPhoneme5(Number(b.dataset.phoneme5)));bind();};
function mobileNav5(){const aside=document.querySelector('aside');if(!aside||$('#mobile-menu5')?.dataset.ready==='yes')return;const toggle=document.createElement('button');toggle.id='mobile-menu5';toggle.className='mobile-menu5';toggle.dataset.ready='yes';toggle.setAttribute('aria-controls','nav');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰ القائمة';aside.prepend(toggle);toggle.onclick=()=>{const open=aside.classList.toggle('nav-open5');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'✕ إغلاق القائمة':'☰ القائمة';};}
const goBefore5=go;go=function(v){goBefore5(v);document.querySelector('aside')?.classList.remove('nav-open5');const t=document.getElementById?.('mobile-menu5');if(t){t.setAttribute('aria-expanded','false');t.textContent='☰ القائمة';}};
function isolateMixed5(root){if(!document.createTreeWalker||!root)return;const walker=document.createTreeWalker(root,4);const nodes=[];let node;while((node=walker.nextNode()))if(/[\u0600-\u06ff]/.test(node.textContent)&&/[A-Za-zÄÖÜäöüß]/.test(node.textContent)&&!node.parentElement.closest('script,style,textarea,input,bdi,[lang="de"],[lang="en"],[dir="ltr"]'))nodes.push(node);nodes.forEach(node=>{const frag=document.createDocumentFragment(),re=/[A-Za-zÄÖÜäöüß][A-Za-zÄÖÜäöüß0-9 /+.-]*[A-Za-zÄÖÜäöüß0-9]|[A-Za-z]/g;let pos=0,m;while((m=re.exec(node.textContent))){frag.append(document.createTextNode(node.textContent.slice(pos,m.index)));const bdi=document.createElement('bdi');bdi.dir='ltr';bdi.textContent=m[0];frag.append(bdi);pos=re.lastIndex;}frag.append(document.createTextNode(node.textContent.slice(pos)));node.replaceWith(frag);});}
const renderBefore5=render;render=function(){renderBefore5();isolateMixed5($('#app'));};
const modalBefore5=showModal;showModal=function(html){modalBefore5(html);isolateMixed5($('#modal'));};
const lessonFinal5=lessonPage4;lessonPage4=function(id){lessonFinal5(id);$('#page-name').textContent='مسارات التعلّم / '+TOPICS.find(t=>t.id===id).title;isolateMixed5($('#app'));};
